(6833674, 1027511, 10785, '<td valign="top"><img alt="'' . substr(''//www.dpchallenge.com/images/user_icon/21.gif'', strrpos(''//www.dpchallenge.com/images/user_icon/21.gif'', ''/'') + 1) . ''" border="0" src="//www.dpchallenge.com/images/user_icon/21.gif"/> <a href="//www.dpchallenge.com/profile.php?USER_ID=74588" rel="nofollow" target="_blank">cutout</a>''s style!! Very good shadows and light coupled with wonderful noise grain and just a hint of an object succeeds in creating the vintage look of a dutch master! Now get that water Martha!!</td>', ' cutout''s style!! Very good shadows and light coupled with wonderful noise grain and just a hint of an object succeeds in creating the vintage look of a dutch master! Now get that water Martha!!', '2012-08-02 15:20:53.000000', NULL, 1),
(6833687, 1027527, 10785, '<td valign="top">Love the secret little framed spot where the camp is nestled in and the wonderful surrounding landscape with the layers of forest throughout to add depth. The water leads you right in to the subject. I could see this hung in one of those thinner 1" gold colored frames on the wall of a hunting lodge with some coffee stained matting!</td>', 'Love the secret little framed spot where the camp is nestled in and the wonderful surrounding landscape with the layers of forest throughout to add depth. The water leads you right in to the subject. I could see this hung in one of those thinner 1" gold colored frames on the wall of a hunting lodge with some coffee stained matting!', '2012-08-02 15:25:36.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6833708, 1027467, 12611, '<td valign="top">great funky shot-polka dots are so photogenic. I like the chair rail.</td>', 'great funky shot-polka dots are so photogenic. I like the chair rail.', '2012-08-02 15:47:51.000000', NULL, 1),
(6833710, 1027414, 12611, '<td valign="top">I would have cropped out that shoulder, but it still works well, great model, fancy phone.</td>', 'I would have cropped out that shoulder, but it still works well, great model, fancy phone.', '2012-08-02 15:49:05.000000', NULL, 1),
(6833711, 1027862, 12611, '<td valign="top">gray and fading.</td>', 'gray and fading.', '2012-08-02 15:49:19.000000', NULL, 1),
(6833713, 1027831, 12611, '<td valign="top">Rich and vibrant- and a terrific use of matting.</td>', 'Rich and vibrant- and a terrific use of matting.', '2012-08-02 15:51:17.000000', NULL, 1),
(6833937, 1027859, 93565, '<td valign="top">I''d like to see more details of the engine itself, up close. This is a very impersonal shot of the engine to me, as it doesn''t accentuate the curves, the angles of the engine, but is instead centered and static.</td>', 'I''d like to see more details of the engine itself, up close. This is a very impersonal shot of the engine to me, as it doesn''t accentuate the curves, the angles of the engine, but is instead centered and static.', '2012-08-02 23:46:46.000000', NULL, 1),
(6833938, 1027532, 93565, '<td valign="top">The red lighting adds an interesting bit to this.</td>', 'The red lighting adds an interesting bit to this.', '2012-08-02 23:47:33.000000', NULL, 1),
(6833946, 1027609, 93565, '<td valign="top">I''d like to see the vantage point of this shot changed from the standard eye level, and have us focusing more on some particular part. It feels aimless, like the viewer is a deer in headlights standing in a place that is supposed to be comfortable and inviting. Perhaps by getting closer to and accentuating the rows of vintage style seats, for instance, this would have been improved.</td>', 'I''d like to see the vantage point of this shot changed from the standard eye level, and have us focusing more on some particular part. It feels aimless, like the viewer is a deer in headlights standing in a place that is supposed to be comfortable and inviting. Perhaps by getting closer to and accentuating the rows of vintage style seats, for instance, this would have been improved.', '2012-08-02 23:51:18.000000', NULL, 1),
(6833951, 1027516, 93565, '<td valign="top">Curious if you used a cigarette behind the cup for the "steam." A very carefully crafted scene, and done quite well. I''ve a sneaking suspicion I know who''s this is...</td>', 'Curious if you used a cigarette behind the cup for the "steam." A very carefully crafted scene, and done quite well. I''ve a sneaking suspicion I know who''s this is...', '2012-08-02 23:52:29.000000', NULL, 1),
