(6835638, 1027319, 96751, '<td valign="top">Great pov. The editing is spot on, great tonal range</td>', 'Great pov. The editing is spot on, great tonal range', '2012-08-05 21:36:30.000000', NULL, 1),
(6835639, 1027465, 96751, '<td valign="top">Nice, low pov. Great colors and contrast</td>', 'Nice, low pov. Great colors and contrast', '2012-08-05 21:37:36.000000', NULL, 1),
(6835640, 1027490, 96751, '<td valign="top">The light in this old barn is fabulous.</td>', 'The light in this old barn is fabulous.', '2012-08-05 21:37:55.000000', NULL, 1),
(6835642, 1027543, 96751, '<td valign="top">LOVE this, and a terrific use of dof. I think you could have cropped a little off the left, even if it meant losing the tip of the brake; I feel it''s a little right-heavy as is</td>', 'LOVE this, and a terrific use of dof. I think you could have cropped a little off the left, even if it meant losing the tip of the brake; I feel it''s a little right-heavy as is', '2012-08-05 21:40:24.000000', NULL, 1),
