INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6835659, 1027874, 96751, '<td valign="top">Ha! What a cutie, and the radio is terrific. A couple of things have a negative impact on an otherwise delightful shot: the shadow starts/stops too abruptly to my eye, and it''s too sharp; a little soft focus would have added more "vintage" quality to the shot.</td>', 'Ha! What a cutie, and the radio is terrific. A couple of things have a negative impact on an otherwise delightful shot: the shadow starts/stops too abruptly to my eye, and it''s too sharp; a little soft focus would have added more "vintage" quality to the shot.', '2012-08-05 22:07:07.000000', NULL, 1),
