(6836664, 1027609, 52549, '<td valign="top">Great shot, Eliza. So pleased it made top 10 for you.</td>', 'Great shot, Eliza. So pleased it made top 10 for you.', '2012-08-07 08:04:16.000000', NULL, 0),
(6837035, 1027820, 66384, '<td valign="top">This jumped off the screen and screamed Currier and Ives when I opened it. It demanded a 10. I had no suspicion it was yours, Wendy. Congratulations on another perfect interpretation and execution of the theme.</td>', 'This jumped off the screen and screamed Currier and Ives when I opened it. It demanded a 10. I had no suspicion it was yours, Wendy. Congratulations on another perfect interpretation and execution of the theme.', '2012-08-07 17:35:23.000000', NULL, 0),
(6837176, 1027511, 10785, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by balancedfox:</b></div><hr/><i> I like the processing. Without the title, I wouldn''t have got it. I hope the DPC voters appreciate it! </i></td></tr></table> <br/> <br/>Can you fill me in because I don''t get it even with the title! Even though I loved this!!</td>', 'Originally posted by balancedfox: I like the processing. Without the title, I wouldn''t have got it. I hope the DPC voters appreciate it!   Can you fill me in because I don''t get it even with the title! Even though I loved this!!', '2012-08-07 22:20:13.000000', NULL, 0),
