(6848027, 1027453, 63398, '<td valign="top">Umm....that''s a TD.....</td>', 'Umm....that''s a TD.....', '2012-08-24 13:39:12.000000', NULL, 0),
(6854148, 1026810, 43463, '<td valign="top">What a fabulous portrait of the new addition to the family, Janine! Love the composition - the lighting and the color along with the knitted hat &amp; diaper cover really give a vintage nostalgic feel to the photo. I like the basket - plays into the old European thought of a special delivery from the stork. Enjoy the new grandchild - he looks sooo cute!</td>', 'What a fabulous portrait of the new addition to the family, Janine! Love the composition - the lighting and the color along with the knitted hat & diaper cover really give a vintage nostalgic feel to the photo. I like the basket - plays into the old European thought of a special delivery from the stork. Enjoy the new grandchild - he looks sooo cute!', '2012-09-02 01:14:13.000000', NULL, 0),
(6854175, 1026810, 30982, '<td valign="top">This is adorable!!</td>', 'This is adorable!!', '2012-09-02 03:43:04.000000', NULL, 0),
(6862528, 1026810, 67697, '<td valign="top">Did not see this.  So totally fantastic!  What a beautiful photo of your new precious gift :)</td>', 'Did not see this.  So totally fantastic!  What a beautiful photo of your new precious gift :)', '2012-09-12 19:49:51.000000', NULL, 0),
(7017486, 1027615, 159723, '<td valign="top">wow! so beautiful!</td>', 'wow! so beautiful!', '2013-04-10 05:41:04.000000', NULL, 0),
(7088083, 1026810, 74559, '<td valign="top">I''m not particularly fond of babies, and yet this image reached out and grabbed me...made me smile and think "oh, yes!". Gorgeous. Now, if you could just put a kitten in this basket... ;-)<br/>ETA: the crocheted diaper and helmet are priceless!<br/><br/><i>Message edited by author 2013-08-15 21:05:46.</i></td>', 'I''m not particularly fond of babies, and yet this image reached out and grabbed me...made me smile and think "oh, yes!". Gorgeous. Now, if you could just put a kitten in this basket... ;-)ETA: the crocheted diaper and helmet are priceless!', '2013-08-15 22:04:44.000000', '2013-08-15 22:05:46.000000', 0),
(7175140, 1026810, 28742, '<td valign="top">Don''t know how I''ve not seen this before - I love it! Really awesome.</td>', 'Don''t know how I''ve not seen this before - I love it! Really awesome.', '2014-02-12 05:43:09.000000', NULL, 0),
